struct Vert {
    vec3 col;
};

struct Triangle2 {
    vec2 a;
    vec2 b;
    vec2 c;
};

struct Triangle3 {
    vec3 a;
    vec3 b;
    vec3 c;
};

vec2 CalcUv(vec2 p, Triangle2 tp, Triangle2 tuv) {
    float w1p1 = (tp.b.y-tp.c.y)*(p.x-tp.c.x)+(tp.c.x-tp.b.x)*(p.y-tp.c.y);
    float w1p2 = (tp.b.y-tp.c.y)*(tp.a.x-tp.c.x)+(tp.c.x-tp.b.x)*(tp.a.y-tp.c.y);
    float w1 = w1p1/w1p2;

    float w2p1 = (tp.c.y-tp.a.y)*(p.x-tp.c.x)+(tp.a.x-tp.c.x)*(p.y-tp.c.y);
    float w2p2 = (tp.b.y-tp.c.y)*(tp.a.x-tp.c.x)+(tp.c.x-tp.b.x)*(tp.a.y-tp.c.y);
    float w2 = w2p1/w2p2;

    float w3 = 1. - w1 - w2;

    return w1*tuv.a + w2*tuv.b + w3*tuv.c;
}

float area(Triangle2 tri) {
    return (tri.a.x*(tri.b.y-tri.c.y) + tri.b.x*(tri.c.y-tri.a.y) + tri.c.x*(tri.a.y-tri.b.y))/2.;
}

