bool isInside(vec2 p, Triangle2 tri) {
    float s = (tri.a.x-tri.c.x)*(p.y-tri.c.y)-(tri.a.y-tri.c.y)*(p.x-tri.c.x);
    float t = (tri.b.x-tri.a.x)*(p.y-tri.a.y)-(tri.b.y-tri.a.y)*(p.x-tri.a.x);

    if((s<0.) != (t<0.) && s != 0. && t  != 0.) return false;

    float d = (tri.c.x-tri.b.x) * (p.y - tri.b.y) - (tri.c.y - tri.b.y) * (p.x - tri.b.x);
    return d == 0. || (d<0.) == (s+t <= 0.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord + (iMouse.xy-iResolution.xy/2.)) / iResolution.xy;
    if(iMouse.xy == vec2(0.)) uv = fragCoord / iResolution.xy;
    Triangle2 ts[2];
    Triangle2 uvs[2];

    ts[0] = Triangle2(vec2(0.,0.),vec2(0.,1.),vec2(1.,0.));
    uvs[0] = Triangle2(vec2(0.,0.),vec2(0.,1.),vec2(1.,0.));
    ts[1] = Triangle2(vec2(1.,0.),vec2(1.,1.),vec2(0.,1.));
    uvs[1] = Triangle2(vec2(1.,0.),vec2(1.,1.),vec2(0.,1.));

    fragColor = vec4(0.,0.,.3,1.);
    for(int i = 0; i < ts.length(); i++) {
        if(isInside(uv,ts[i])) {
            vec2 textureUv = CalcUv(uv,ts[i],uvs[i]);

            vec3 col = texture(iChannel0,textureUv).xyz;

            fragColor = vec4(col,1.);
            if(textureUv.x>1.||textureUv.x<0.||textureUv.y>1.||textureUv.y<0.) fragColor = vec4(.15,.15,3.,1.);
        }
    }
}
